Color? _exactQolipHexColor(String value) {
  final normalized = value.trim();
  if (!RegExp(r'^#[0-9A-Fa-f]{6}$').hasMatch(normalized)) {
    return null;
  }
  final rgb = int.parse(normalized.substring(1), radix: 16);
  return Color(0xFF000000 | rgb);
}
